    "author": "",
    "description": "36氪获悉，中航光电公告，2026年第三季度营业收入68.82亿元，同比增长47.87%；归母净利润8.16亿元，同比增长172.13%；扣非净利润8.26亿元，同比增长188.45%。2026年前三季度营业收入181.22亿元，同比增长14.42%；归母净利润19.35亿元，同比增长11.42%；扣非净利润19.1亿元，同比增长12.29%。",
    "content": "36氪获悉，中航光电公告，2026年第三季度营业收入68.82亿元，同比增长47.87%；归母净利润8.16亿元，同比增长172.13%；扣非净利润8.26亿元，同比增长188.45%。2026年前三季度营业收入181.22亿元，同比增长14.42%；归母净利润19.35亿元，同比增长11.42%；扣非净利润19.1亿元，同比增长12.29%。"
