    "content": "知情人士透露，半导体元器件厂商安森美半导体（Onsemi）正在洽谈收购成立已有16年的芯片初创公司Ferric，交易对价接近10亿美元。这笔交易折射出市场对能够满足AI芯片巨大能耗需求的技术，需求正持续走高。（新浪财经）"
