    "pub_date": "2026-10-28 19:17:23",
    "author": "",
    "description": "恒星变“老”会膨胀，靠得太近的行星会被它“吞掉”，这是天文学一直以来的认知，但我国天文学家的一项最新发现颠覆了这个认知。近日，云南大学物理与天文学院钱声帮教授率团队在美国《国家科学院学报》发表论文，宣布发现三颗本该被恒星吞噬却“活”下来的系外行星。",
    "content": "恒星变“老”会膨胀，靠得太近的行星会被它“吞掉”，这是天文学一直以来的认知，但我国天文学家的一项最新发现颠覆了这个认知。近日，云南大学物理与天文学院钱声帮教授率团队在美国《国家科学院学报》发表论文，宣布发现三颗本该被恒星吞噬却“活”下来的系外行星。"
