    "description": "新华社马德里10月28日电（记者龚哲 谢宇智）西班牙卡斯蒂利亚-拉曼查自治区首府托莱多当地时间28日上午发生一起高速铁路列车相撞事故。据西班牙媒体消息，事故目前已造成至少50人死亡、179人受伤。中国驻西班牙大使馆对新华社记者说，相撞列车上有4名中国公民，暂无中国公民死亡报告。 据西班牙媒体援引紧急救援部门消息报道，当地时间9时左右，一列行驶中的西班牙国家铁路公司列车在托莱多附近追尾另一列停在铁轨上的伊尔约公司列车，导致后者的两节车厢脱…",
    "content": "新华社马德里10月28日电（记者龚哲 谢宇智）西班牙卡斯蒂利亚-拉曼查自治区首府托莱多当地时间28日上午发生一起高速铁路列车相撞事故。据西班牙媒体消息，事故目前已造成至少50人死亡、179人受伤。中国驻西班牙大使馆对新华社记者说，相撞列车上有4名中国公民，暂无中国公民死亡报告。 据西班牙媒体援引紧急救援部门消息报道，当地时间9时左右，一列行驶中的西班牙国家铁路公司列车在托莱多附近追尾另一列停在铁轨上的伊尔约公司列车，导致后者的两节车厢脱轨并坠下路堤。 据报道，两列列车分别载有147名乘客和397名乘客。消防员、警方…"
