    "content": "主动权益基金三季度重仓股大洗牌，科技仍坐“主桌”，但资金筹码已重新排队。 截至10月27日，公募基金2026年三季度报告已全部披露完毕，主动权益基金（包括普通股票型基金、偏股混合型基金、平衡混合型基金、灵活配置型基金）的持仓底牌已全面揭晓。对比二季度末与三季度末的前二十大重仓股数据，可以发现公募基金在坚守科技主线的同时，进行了剧烈的结构性调仓。 从行业分布来看，按公募基金持股总市值排序，信息技术板块依然占据绝对多数，但在算力硬件、半导体设备及消费电子等细分领域内部，资金出现了明显的分化与腾挪；此外，部分资金溢出至医…"
