    "author": "wisteen",
    "description": "就在刚才，你有 agent 停下来问能不能部署。你确定有一个停了，但不知道是哪一个。 形状永远一样：Mac 上跑 Claude Code ，构建机上跑 Codex ，某台一周登两次的服务器上还跑着别的。它们都会在部署、删除、安装前停下来等一个 yes 。yes 只花两秒，吃掉整个晚上的是找出谁在哪台机器上等你。 最顺手的办法是每台机器一个 tmux 、每个项目一个终端，再加一个翻对 scrollback 的习惯。机器一多，那个路由器就是…",
