    "content": "新华社北京10月28日电（记者冯歆然、曹嘉玥）瑞士联邦主席帕姆兰将于10月30日至11月1日来华进行工作访问。外交部发言人郭嘉昆28日在例行记者会上介绍此访安排和中方期待。 “中方欢迎瑞士联邦主席帕姆兰来华访问。”郭嘉昆说，习近平主席将同他会见。 “今年是中瑞建立创新战略伙伴关系10周年。当前，中瑞关系发展良好，各领域合作成果丰硕，特别是自贸合作成为两国关系最大亮点。”郭嘉昆表示，瑞士是最早同中国签订自贸协定的欧洲大陆国家，协定生效10多年来，为中瑞双边经贸往来发挥了积极推动作用。今年8月，瑞士再次成为率先完成同中…"
