    "category": "新闻",
    "title": "李鸿忠会见欧洲议会国际贸易委员会代表团",
    "link": "http://www.news.cn/20261028/1aa38d152a904cb1a97a5e3bb0c26d0e/c.html",
    "pub_date": "2026-10-28 17:30:46",
    "author": "",
    "description": "新华社北京10月28日电 中共中央政治局委员、全国人大常委会副委员长李鸿忠28日在京会见欧洲议会国际贸易委员会主席朗格率领的代表团。 李鸿忠表示，中欧经贸关系的本质是优势互补、互利共赢。中欧双方作为全面战略伙伴，完全可以通过平等对话找到互利双赢的解决办法。中国全国人大愿同欧洲议会一道，巩固良好交往势头，为促进中欧关系健康稳定发展发挥积极作用。 朗格表示，欧洲议会国际贸易委员会愿同中方加强对话合作，推动欧中贸易稳定平衡发展。",
    "content": "新华社北京10月28日电 中共中央政治局委员、全国人大常委会副委员长李鸿忠28日在京会见欧洲议会国际贸易委员会主席朗格率领的代表团。 李鸿忠表示，中欧经贸关系的本质是优势互补、互利共赢。中欧双方作为全面战略伙伴，完全可以通过平等对话找到互利双赢的解决办法。中国全国人大愿同欧洲议会一道，巩固良好交往势头，为促进中欧关系健康稳定发展发挥积极作用。 朗格表示，欧洲议会国际贸易委员会愿同中方加强对话合作，推动欧中贸易稳定平衡发展。"
