    "description": "新华社上海10月28日电（记者杨有宗）上海市浦东新区统计局近日发布的一组数据引人关注，今年前三季度，浦东新区全区新能源汽车产量同比增长50.3%，占全部整车产量比重达88%。变压器、电力电容器、储能用锂离子电池等产品产量同比分别增长23%、79.8%和1.6倍。浦东新区新能源汽车、锂电池、光伏产品“新三样”产业发展呈现规模可观、支撑有力态势。 从海关数据看，浦东新区前三季度“新三样”出口额合计同比增长81.5%，拉动浦东新区出口总额增速…",
    "content": "新华社上海10月28日电（记者杨有宗）上海市浦东新区统计局近日发布的一组数据引人关注，今年前三季度，浦东新区全区新能源汽车产量同比增长50.3%，占全部整车产量比重达88%。变压器、电力电容器、储能用锂离子电池等产品产量同比分别增长23%、79.8%和1.6倍。浦东新区新能源汽车、锂电池、光伏产品“新三样”产业发展呈现规模可观、支撑有力态势。 从海关数据看，浦东新区前三季度“新三样”出口额合计同比增长81.5%，拉动浦东新区出口总额增速9.6个百分点，其中，新能源汽车、锂电池、太阳能电池出口额同比分别增长88.2%…"
